const allSubjects=Object.values(groups).flat();const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}};const btn=(label,act,cls='primary')=>`<button class="${cls}" data-act="${act}">${label}</button>`;
